import{c as a,Q as s,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/LoadData2DParamsV2%E7%BB%93%E6%9E%84%E4%BD%93%E5%8F%82%E6%95%B0%E7%A4%BA%E4%BE%8B%EF%BC%88%E4%BB%A5half%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B-%E4%B8%8D%E5%90%AF%E7%94%A8%E8%BD%AC%E7%BD%AE%E4%B8%BA%E4%BE%8B%EF%BC%89.RVYnTEuh.png",m=JSON.parse('{"title":"Load2D","description":"","frontmatter":{},"headers":[{"level":1,"title":"Load2D","slug":"load2d"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2D.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2D.md"}'),d={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load2D.md"};function i(p,t,r,o,c,_){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="load2d" tabindex="-1">Load2D <a class="header-anchor" href="#load2d" aria-label="Permalink to &quot;Load2D&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Load2D支持如下数据通路的搬运：</p><p>GM-&gt;A1; GM-&gt;B1; GM-&gt;A2; GM-&gt;B2;</p><p>A1-&gt;A2; B1-&gt;B2。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>Load2D接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LoadData2DParams&amp; loadDataParams)</span></span>
<span class="line"><span>template &lt;typename T&gt; </span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src, const LoadData2DParams&amp; loadDataParams)</span></span></code></pre></div></li><li><p>Load2Dv2接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src,const LoadData2DParamsV2&amp; loadDataParam)</span></span>
<span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src,const LoadData2DParamsV2&amp; loadDataParam)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。 Load2D接口 Atlas 训练系列产品，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/half Atlas 推理系列产品AI Core，支持的数据类型为：int4b_t/uint8_t/int8_t/uint16_t/int16_t/half，int4b_t仅支持A1-&gt;A2，B1-&gt;B2通路 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持数据类型为：int4b_t/uint8_t/int8_t/uint16_t/int16_t/half/bfloat16_t/uint32_t/int32_t/float，int4b_t仅支持A1-&gt;A2，B1-&gt;B2通路 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持数据类型为：int4b_t/uint8_t/int8_t/uint16_t/int16_t/half/bfloat16_t/uint32_t/int32_t/float，int4b_t仅支持A1-&gt;A2，B1-&gt;B2通路 Atlas 200I/500 A2 推理产品，支持数据类型为：uint8_t/int8_t/uint16_t/int16_t/half/bfloat16_t/uint32_t/int32_t/float Ascend 950PR/Ascend 950DT，支持数据类型为：uint8_t/int8_t/uint16_t/int16_t/half/bfloat16_t/uint32_t/int32_t/float，仅支持如下数据通路: GM-&gt;A1; GM-&gt;B1; A1-&gt;A2; B1-&gt;B2。 Kirin X90，支持的数据类型为：int8_t/half Kirin 9030，支持的数据类型为：half Load2Dv2接口 Ascend 950PR/Ascend 950DT， GM-&gt;A1、GM-&gt;B1时，支持数据类型为：int8_t/uint8_t/fp4x2_e2m1_t/fp4x2_e1m2_t/hifloat8_t/fp8_e5m2_t/fp8_e4m3fn_t/half/bfloat16_t/int32_t/uint32_t/floatA1-&gt;A2、B1-&gt;B2时，支持数据类型为： int8_t/uint8_t/fp4x2_e2m1_t/fp4x2_e1m2_t/hifloat8_t/fp8_e5m2_t/fp8_e4m3fn_t/half/bfloat16_t/int32_t/uint32_t/float</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。 数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下： A2：ZZ格式/NZ格式；对应的分形大小为16 * (32B / sizeof(T))。B2：ZN格式；对应的分形大小为 (32B / sizeof(T)) * 16。A1/B1：无格式要求，一般情况下为NZ格式。NZ格式下，对应的分形大小为16 * (32B / sizeof(T))。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。 数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为： LoadData2DParams，具体参考表3。LoadData2DParamsV2，具体参考表4。 上述结构体参数定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> LoadData2DParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>startIndex</td><td>分形矩阵ID，说明搬运起始位置为源操作数中第几个分形（0为源操作数中第1个分形矩阵）。取值范围：startIndex∈[0, 65535] 。单位：512B。默认为0。</td></tr><tr><td>repeatTimes</td><td>迭代次数，每个迭代可以处理512B数据。取值范围：repeatTimes∈[1, 255]。</td></tr><tr><td>srcStride</td><td>相邻迭代间，源操作数前一个分形与后一个分形起始地址的间隔，单位：512B。取值范围：src_stride∈[0, 65535]。默认为0。</td></tr><tr><td>sid</td><td>预留参数，配置为0即可。</td></tr><tr><td>dstGap</td><td>相邻迭代间，目的操作数前一个分形结束地址与后一个分形起始地址的间隔，单位：512B。取值范围：dstGap∈[0, 65535]。默认为0。 注：Atlas 训练系列产品此参数不使能。</td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false: true：启用false：不启用 注意：只有A1-&gt;A2和B1-&gt;B2通路才能使能转置，使能转置功能时，源操作数、目的操作数仅支持b16数据类型。</td></tr><tr><td>addrMode</td><td>控制地址更新方式，默认为false： true：递减，每次迭代在前一个地址的基础上减去srcStride。false：递增，每次迭代在前一个地址的基础上加上srcStride。</td></tr></tbody></table><p><strong>表 4</strong> LoadData2DParamsV2结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mStartPosition</td><td>以M*K矩阵为例，源矩阵M轴方向的起始位置，单位为16个元素。</td></tr><tr><td>kStartPosition</td><td>以M*K矩阵为例，源矩阵K轴方向的起始位置，单位为32B。</td></tr><tr><td>mStep</td><td>以M*K矩阵为例，源矩阵M轴方向搬运长度，单位为16 element。取值范围：mStep∈[0, 255]。 通过ifTranspose参数启用转置功能时，mStep除需满足 [0, 255]的取值范围外，还需满足以下额外约束： 当数据类型为b4时，mStep必须是4的倍数；当数据类型为b8时，mStep必须是2的倍数；当数据类型为b16时，mStep必须是1的倍数；当数据类型为b32时，mStep无额外约束。</td></tr><tr><td>kStep</td><td>以M*K矩阵为例，源矩阵K轴方向搬运长度，单位为32B。取值范围：kStep∈[0, 255]。 通过ifTranspose参数启用转置功能时，kStep除需满足[0,255]的取值范围外，还需满足以下额外约束： 当数据类型为b4、b8或b16时，kStep没有额外约束；当数据类型为b32时，kStep必须是2的倍数。</td></tr><tr><td>srcStride</td><td>以M*K矩阵为例，源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512B。</td></tr><tr><td>dstStride</td><td>以M*K矩阵为例，目标矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔，单位：512B。</td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false。 true：启用false：不启用 注意：只有A1-&gt;A2和B1-&gt;B2通路才能使能转置。使能转置功能时，支持的数据类型约束如下： 对于Ascend 950PR/Ascend 950DT，源操作数、目的操作数支持b4、b8、b16、b32数据类型。</td></tr><tr><td>sid</td><td>预留参数，配置为0即可。</td></tr></tbody></table><p>LoadData2DParamsV2结构体在不启用转置时，示意图如下，参数设置值和解释说明如下：</p><ul><li>mStartPosition = 2，表示源矩阵M轴方向的起始位置为第32个元素（2*16个元素）。</li><li>kStartPosition = 2，表示源矩阵K轴方向的起始位置为第32个元素（2*32B）。</li><li>mStep = 2，表示源矩阵M轴方向搬运长度为32个元素（2*16个元素）。</li><li>kStep = 3，表示源矩阵K轴方向搬运长度为48个元素（3*32B）。</li><li>srcStride = 5，表示源矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔为1280个元素（5*512B）。</li><li>dstStride = 3，表示目的矩阵K方向前一个分形起始地址与后一个分形起始地址的间隔为768个元素（3*512B）。</li><li>ifTranspose = false，表示不启用转置。</li><li>sid = 0，预留参数，配置为0即可。</li></ul><p><strong>图 1</strong> LoadData2DParamsV2结构体参数示例（以half数据类型，不启用转置为例）<br><img src="`+l+`" alt="" title="LoadData2DParamsV2结构体参数示例（以half数据类型-不启用转置为例）"></p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>对于Atlas 推理系列产品AI Core，在配合Mmad接口使用、B矩阵数据类型为S4场景下，如果通过ifTranspose参数启用转置，只支持64*64的分形。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整使用样例请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/01_matrix_compute/load_data_l12l0" target="_blank" rel="noreferrer">LoadData_L12L0样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Load2d: Nz -&gt; Zz</span></span>
<span class="line"><span>uint32_t m = 40;</span></span>
<span class="line"><span>uint32_t k = 70;</span></span>
<span class="line"><span>uint32_t fractalShape[2] = {16, 32 / sizeof(half)};</span></span>
<span class="line"><span>uint32_t fractalSize = fractalShape[0] * fractalShape[1];</span></span>
<span class="line"><span>uint32_t dstOffset = (k + fractalShape[1] - 1) / fractalShape[1] * fractalSize;</span></span>
<span class="line"><span>uint32_t srcOffset = fractalSize;</span></span>
<span class="line"><span>uint16_t mStep = (m + fractalShape[0] - 1) / fractalShape[0];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::LoadData2DParams loadDataParams;</span></span>
<span class="line"><span>loadDataParams.repeatTimes = (k + fractalShape[1] - 1) / fractalShape[1];</span></span>
<span class="line"><span>loadDataParams.srcStride = mStep;</span></span>
<span class="line"><span>loadDataParams.dstGap = 0;</span></span>
<span class="line"><span>loadDataParams.ifTranspose = false;</span></span>
<span class="line"><span>for (int i = 0; i &lt; mStep; ++i) {</span></span>
<span class="line"><span>	AscendC::LoadData(a2Local[i * dstOffset], a1Local[i * srcOffset], loadDataParams);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Load2Dv2: Nz -&gt; Nz</span></span>
<span class="line"><span>AscendC::LoadData2DParamsV2 loadDataParams;</span></span>
<span class="line"><span>loadDataParams.mStep = mStep;</span></span>
<span class="line"><span>loadDataParams.kStep = (k + fractalShape[1] - 1) / fractalShape[1];</span></span>
<span class="line"><span>loadDataParams.srcStride = mStep;</span></span>
<span class="line"><span>loadDataParams.dstStride = mStep;</span></span>
<span class="line"><span>loadDataParams.ifTranspose = false;</span></span>
<span class="line"><span>AscendC::LoadData(a2Local, a1Local, loadDataParams);</span></span></code></pre></div>`,28)])])}const f=a(d,[["render",i]]);export{m as __pageData,f as default};
